function escapeHtml(value){const node=document.createElement("div");node.textContent=String(value??"");return node.innerHTML}
function toDate(value){if(value?.toDate)return value.toDate();if(Number.isFinite(Number(value?.seconds)))return new Date(Number(value.seconds)*1000+Math.floor(Number(value.nanoseconds||0)/1e6));const date=new Date(value||0);return Number.isNaN(date.getTime())?new Date(0):date}
