function notify(message,error=false){const toast=$("toast");toast.textContent=message;toast.className=`toast show${error?" error":""}`;clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.className="toast",2600)}
function notifyUndo(message,callback){const toast=$("toast");toast.textContent=message;const button=document.createElement("button");button.type="button";button.className="toast-undo";button.textContent="復原";button.addEventListener("click",()=>{clearTimeout(notify.timer);callback();toast.className="toast"},{once:true});toast.appendChild(button);toast.className="toast show";clearTimeout(notify.timer);notify.timer=setTimeout(()=>toast.className="toast",7000)}
