let ledgerSyncTimer=null,legacySyncTimer=null,goalSyncTimer=null;
function scheduleLedgerSync(){clearTimeout(ledgerSyncTimer);ledgerSyncTimer=setTimeout(syncLedgerSnapshot,900)}
function scheduleLegacySync(){clearTimeout(legacySyncTimer);legacySyncTimer=setTimeout(syncLegacySnapshot,900)}
