async function syncLegacySnapshot(){if(!db||!state.legacyReachable||!state.legacyDirty||state.legacySyncing||navigator.onLine===false)return;const revision=state.legacyRevision,deleted=[...state.legacyDeletedTransactions],operations=[];state.legacyWallets.forEach(wallet=>{const record={balance:Number(wallet.balance)||0,label:wallet.label,schemaVersion:3,updatedAt:firebase.firestore.FieldValue.serverTimestamp()};operations.push(batch=>batch.set(db.collection("wallets").doc(wallet.id),record,{merge:true}))});state.legacyTransactions.forEach(item=>{const record={...item,time:firebase.firestore.Timestamp.fromDate(toDate(item.time))};delete record.syncStatus;delete record.balanceDelta;operations.push(batch=>batch.set(db.collection("transactions").doc(item.id),record))});deleted.forEach(item=>operations.push(batch=>batch.delete(db.collection("transactions").doc(item.id))));state.legacySyncing=true;render();try{await commitBatchOperations(operations);state.legacyDeletedTransactions=state.legacyDeletedTransactions.filter(item=>!deleted.some(saved=>saved.id===item.id));if(state.legacyRevision===revision){state.legacyTransactions.forEach(item=>{delete item.syncStatus;delete item.balanceDelta});state.legacyDirty=false}state.legacyCloud=!state.legacyDirty;saveLocalLegacy(false,false);if(state.legacyDirty)scheduleLegacySync()}catch(error){console.warn("存錢資料尚未同步，已安全保留本機版本",error);state.legacyCloud=false}finally{state.legacySyncing=false;render()}}
