async function retryPendingSync(){if(!db||navigator.onLine===false)return;if(state.ledgerDirty&&!state.ledgerReachable){const probes=await Promise.allSettled([db.collection("ledgerAccounts").limit(1).get(),db.collection("ledgerTransactions").limit(1).get(),db.collection("settings").doc("household").get(),db.collection("ledgerSettlements").limit(1).get(),db.collection("ledgerTransfers").limit(1).get()]);state.ledgerReachable=probes.every(result=>result.status==="fulfilled")}if(state.legacyDirty&&!state.legacyReachable){const probes=await Promise.allSettled([db.collection("wallets").limit(1).get(),db.collection("transactions").limit(1).get()]);state.legacyReachable=probes.every(result=>result.status==="fulfilled")}await Promise.allSettled([syncLedgerSnapshot(),syncLegacySnapshot(),syncGoalSnapshot()])}
