async function saveGoal(event){event.preventDefault();const id=$("goalEditId").value,existing=state.goals.find(item=>item.id===id),amount=Number($("goalAmount").value),allocated=Number($("goalSaved").value),name=$("goalName").value.trim(),walletId=$("goalWallet").value;if(!name)return notify("請輸入目標名稱",true);if(!Number.isSafeInteger(amount)||!Number.isSafeInteger(allocated)||amount<=0||allocated<0||allocated>amount)return notify("目標與已存金額必須是有效整數",true);if(walletId!=="all"&&!state.legacyWallets.some(wallet=>wallet.id===walletId))return notify("找不到選擇的存錢筒",true);const item={id:id||`goal-${Date.now()}`,name,amount,allocated,targetDate:$("goalDate").value,walletId};existing?Object.assign(existing,item):state.goals.push(item);closeModal();await persistGoals(existing?"目標已更新":"目標已建立")}
async function addToGoal(id){const item=state.goals.find(goal=>goal.id===id);if(!item)return notify("找不到這個目標",true);const remaining=Number(item.amount)-Number(item.allocated||0);if(remaining<=0)return notify("這個目標已經完成");const wallet=state.legacyWallets.find(entry=>entry.id===item.walletId),input=prompt(`要放入「${item.name}」多少錢？\n${wallet?`會同時存入 ${wallet.label}。`:"只調整目標進度，不會改變存錢筒。"}`,String(Math.min(1000,remaining)));if(input===null)return;const amount=Number(input);if(!Number.isSafeInteger(amount)||amount<=0||amount>remaining)return notify("請輸入有效且不超過剩餘目標的整數金額",true);item.allocated=Number(item.allocated||0)+amount;if(wallet){wallet.balance=Number(wallet.balance||0)+amount;state.legacyTransactions.unshift({id:`legacy-goal-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,walletId:wallet.id,who:wallet.label,action:"deposit",type:"存入",amount,note:`存入目標：${item.name}`,category:"目標存錢",goalId:item.id,time:new Date().toISOString(),syncStatus:"local"});saveLocalLegacy(true,true);render();notify(`已放入 ${money.format(amount)}，並存入 ${wallet.label}`)}else await persistGoals(`已放入 ${money.format(amount)}`)}
function togglePrivacy(){state.private=!state.private;localStorage.setItem("moneycanPrivate",state.private?"1":"0");render();$("privacyButton").textContent=state.private?"◌":"◉"}
function toggleTheme(){state.dark=!state.dark;localStorage.setItem("moneycanDark",state.dark?"1":"0");render()}
async function saveBudget(event){event.preventDefault();const category=$("budgetCategory").value,amount=Number($("budgetAmount").value);if(!Number.isSafeInteger(amount)||amount<=0)return notify("請輸入有效預算",true);const existing=state.budgets.find(item=>item.category===category);existing?existing.amount=amount:state.budgets.push({category,amount});$("budgetAmount").value="";await persistMembers();notify("預算已儲存")}
async function deleteBudget(category){state.budgets=state.budgets.filter(item=>item.category!==category);await persistMembers();notify("預算已移除")}
async function materializeRecurring(){const now=new Date(),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,"0")}`,templates=state.transactions.filter(item=>item.recurring&&!item.recurringParent);for(const template of templates){const original=toDate(template.time),originalMonth=`${original.getFullYear()}-${String(original.getMonth()+1).padStart(2,"0")}`;if(originalMonth===month||state.transactions.some(item=>item.recurringParent===template.id&&item.occurrenceMonth===month))continue;const day=Math.min(original.getDate(),new Date(now.getFullYear(),now.getMonth()+1,0).getDate()),time=new Date(now.getFullYear(),now.getMonth(),day,12),account=accountById(template.accountId);if(!account)continue;await persistTransaction({...template,id:`recurring-${template.id}-${month}`,time:time.toISOString(),date:time.toLocaleDateString("en-CA"),recurring:false,recurringParent:template.id,occurrenceMonth:month},account);notify("已建立本月固定帳目")}}
async function persistMembers(){saveLocalLedger();render();if(db&&state.cloud)try{await db.collection("settings").doc("household").set({name:state.familyName,members:state.members,budgets:state.budgets,updatedAt:firebase.firestore.FieldValue.serverTimestamp()},{merge:true})}catch(error){console.warn(error)}}
async function addMember(){const name=prompt("新成員名稱（例如：媽媽、哥哥）");if(!name?.trim())return;if(state.members.length>=8)return notify("目前最多 8 位家庭成員",true);let migrated=false;state.transactions.forEach(item=>{if(!Array.isArray(item.participants)||!item.participants.length){item.participants=state.members.map(member=>({id:member.id,name:member.name}));migrated=true}});if(migrated)saveLocalLedger();state.members.push({id:`member-${Date.now()}`,name:name.trim()});await persistMembers();notify("家庭成員已新增，舊帳分攤不會改變")}
async function removeMember(id){const member=memberById(id);if(!member)return;const ownedAccount=state.accounts.find(account=>account.ownerId===id),referenced=state.transactions.some(item=>item.paidBy===id||transactionMembers(item).some(saved=>saved.id===id)||item.allocations?.some(saved=>saved.memberId===id));if(ownedAccount)return notify(`請先處理「${ownedAccount.name}」；有帳戶的成員不能直接移除`,true);if(referenced)return notify("這位成員已有歷史記帳，為避免分攤改變，目前不能移除",true);if(!confirm(`確定移除「${member.name}」嗎？`))return;state.members=state.members.filter(item=>item.id!==id);await persistMembers();notify("家庭成員已移除")}
function exportData(){const payload={schemaVersion:3,exportedAt:new Date().toISOString(),familyName:state.familyName,members:state.members,budgets:state.budgets,accounts:state.accounts,transactions:state.transactions,settlements:state.settlements,transfers:state.transfers,legacyWallets:state.legacyWallets,legacyTransactions:state.legacyTransactions,goals:state.goals},blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`moneycan-backup-${new Date().toLocaleDateString("en-CA")}.json`;link.click();URL.revokeObjectURL(url);notify("完整備份已下載")}
function exportCsv(){const quote=value=>`"${String(value??"").replaceAll('"','""')}"`,rows=[["日期","類型","帳戶","分類","金額","帳本","付款人","備註"],...state.transactions.map(item=>[toDate(item.time).toLocaleDateString("en-CA"),transactionKind(item)==="income"?"收入":"支出",accountById(item.accountId)?.name||"",item.category,item.amount,item.scope==="personal"?"個人":"共同",memberById(item.paidBy)?.name||"",item.note||""])],blob=new Blob(["\ufeff"+rows.map(row=>row.map(quote).join(",")).join("\r\n")],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),link=document.createElement("a");link.href=url;link.download=`moneycan-transactions-${new Date().toLocaleDateString("en-CA")}.csv`;link.click();URL.revokeObjectURL(url);notify("CSV 明細已下載")}
async function importBackup(file){try{const data=JSON.parse(await file.text()),validId=value=>typeof value==="string"&&value.length>0&&value.length<180&&!value.includes("/"),uniqueIds=items=>new Set(items.map(item=>item.id)).size===items.length,validMoney=value=>Number.isSafeInteger(Number(value));if(!Array.isArray(data.accounts)||!Array.isArray(data.transactions)||!data.accounts.length||![...data.accounts,...data.transactions].every(item=>item&&validId(item.id))||!uniqueIds(data.accounts)||!uniqueIds(data.transactions)||!data.accounts.every(item=>validMoney(item.balance))||!data.transactions.every(item=>validMoney(item.amount)&&toDate(item.time).getTime()>0))throw new Error("格式不正確");const optional=["settlements","transfers","legacyWallets","legacyTransactions","goals","members","budgets"];if(optional.some(key=>data[key]!==undefined&&!Array.isArray(data[key])))throw new Error("選用欄位格式不正確");for(const key of ["settlements","transfers","legacyTransactions","goals"])if(Array.isArray(data[key])&&(!data[key].every(item=>item&&validId(item.id))||!uniqueIds(data[key])))throw new Error(`${key} 識別碼不正確`);const accountIds=new Set(data.accounts.map(item=>item.id));if(data.transactions.some(item=>!accountIds.has(item.accountId)))throw new Error("記帳引用了不存在的帳戶");const legacyCount=Array.isArray(data.legacyTransactions)?data.legacyTransactions.length:0,transferCount=Array.isArray(data.transfers)?data.transfers.length:0;if(!confirm(`將還原 ${data.transactions.length} 筆記帳、${transferCount} 筆轉帳與 ${legacyCount} 筆存錢資料，並取代目前本機版本，確定嗎？`))return;const oldTransactionIds=state.transactions.map(item=>item.id),oldSettlementIds=state.settlements.map(item=>item.id),oldTransferIds=state.transfers.map(item=>item.id),oldLegacyIds=state.legacyTransactions.map(item=>item.id);localStorage.setItem("moneyCanRecoveryLedger",localStorage.getItem("moneyCanLedgerV2")||"");localStorage.setItem("moneyCanRecoveryLegacy",localStorage.getItem("familyMoneyBookV2")||"");state.accounts=normalizeAccounts(data.accounts);state.transactions=data.transactions;state.settlements=Array.isArray(data.settlements)?data.settlements:[];state.transfers=Array.isArray(data.transfers)?data.transfers:[];state.members=Array.isArray(data.members)&&data.members.length?data.members:state.members;state.budgets=Array.isArray(data.budgets)?data.budgets:[];if(Array.isArray(data.legacyWallets))state.legacyWallets.forEach(wallet=>{const saved=data.legacyWallets.find(item=>item.id===wallet.id);if(saved)wallet.balance=Number(saved.balance)||0});if(Array.isArray(data.legacyTransactions))state.legacyTransactions=data.legacyTransactions;if(Array.isArray(data.goals))state.goals=data.goals;state.ledgerDeletedTransactions=[...new Set([...state.ledgerDeletedTransactions,...oldTransactionIds.filter(id=>!state.transactions.some(item=>item.id===id))])];state.ledgerDeletedSettlements=[...new Set([...state.ledgerDeletedSettlements,...oldSettlementIds.filter(id=>!state.settlements.some(item=>item.id===id))])];state.ledgerDeletedTransfers=[...new Set([...state.ledgerDeletedTransfers,...oldTransferIds.filter(id=>!state.transfers.some(item=>item.id===id))])];state.legacyDeletedTransactions=[...state.legacyDeletedTransactions,...oldLegacyIds.filter(id=>!state.legacyTransactions.some(item=>item.id===id)&&!state.legacyDeletedTransactions.some(saved=>saved.id===id)).map(id=>({id}))];state.familyName=typeof data.familyName==="string"&&data.familyName.trim()?data.familyName.trim():state.familyName;JSON.stringify({accounts:state.accounts,transactions:state.transactions,transfers:state.transfers,legacyTransactions:state.legacyTransactions});saveLocalLedger();saveLocalLegacy(true,true);localStorage.setItem("moneycanFamilyName",state.familyName);state.cloud=false;state.ledgerCloud=false;state.legacyCloud=false;state.goalCloud=false;render();notify("備份已安全還原，舊版本已保留為復原副本")}catch(error){console.warn("備份匯入失敗",error);notify("無法讀取這份備份，原資料沒有變更",true)}}

document.addEventListener("click",event=>{const route=event.target.closest("[data-route]")?.dataset.route;if(route)return setRoute(route);if(event.target.closest("[data-close-modal]"))return closeModal();const legacyNew=event.target.closest("[data-legacy-new]");if(legacyNew)return openLegacyTransaction(legacyNew.dataset.walletId,legacyNew.dataset.legacyNew);const legacyEdit=event.target.closest("[data-legacy-edit]")?.dataset.legacyEdit;if(legacyEdit)return openLegacyTransaction(null,"deposit",state.legacyTransactions.find(item=>item.id===legacyEdit));const legacyActionButton=event.target.closest("[data-legacy-action]");if(legacyActionButton)return setLegacyAction(legacyActionButton.dataset.legacyAction);const legacyQuick=event.target.closest("[data-legacy-quick]")?.dataset.legacyQuick;if(legacyQuick){$("legacyAmount").value=(Number($("legacyAmount").value)||0)+Number(legacyQuick);return $("legacyAmount").focus()}const settlementPay=event.target.closest("[data-settlement-pay]");if(settlementPay)return openSettlement(settlementPay.dataset.from,settlementPay.dataset.to,Number(settlementPay.dataset.amount));const settlementUndo=event.target.closest("[data-settlement-undo]")?.dataset.settlementUndo;if(settlementUndo)return undoSettlement(settlementUndo);const transferUndo=event.target.closest("[data-transfer-undo]")?.dataset.transferUndo;if(transferUndo)return undoTransfer(transferUndo);const transactionEdit=event.target.closest("[data-transaction-edit]")?.dataset.transactionEdit;if(transactionEdit)return openTransaction(state.transactions.find(item=>item.id===transactionEdit));const accountEdit=event.target.closest("[data-account-edit]")?.dataset.accountEdit;if(accountEdit)return openAccount(accountById(accountEdit));const goalEdit=event.target.closest("[data-goal-edit]")?.dataset.goalEdit;if(goalEdit)return openGoal(state.goals.find(item=>item.id===goalEdit));const goalAdd=event.target.closest("[data-goal-add]")?.dataset.goalAdd;if(goalAdd)return addToGoal(goalAdd);const memberDelete=event.target.closest("[data-member-delete]")?.dataset.memberDelete;if(memberDelete)return removeMember(memberDelete);const budgetDelete=event.target.closest("[data-budget-delete]")?.dataset.budgetDelete;if(budgetDelete)return deleteBudget(budgetDelete)});
$("modalBackdrop").addEventListener("click",event=>{if(event.target===$("modalBackdrop"))closeModal()});document.addEventListener("keydown",event=>{if(event.key==="Escape")closeModal()});
