async function init(){const now=new Date();$("todayText").textContent=now.toLocaleDateString("zh-TW",{year:"numeric",month:"long",day:"numeric",weekday:"short"});await Promise.all([loadLedger(),loadLegacy()]);state.ready=true;await materializeRecurring();refreshAccountFilter();$("legacyWalletFilter").innerHTML='<option value="all">全部存錢筒</option>'+state.legacyWallets.map(item=>`<option value="${item.id}">${escapeHtml(item.label)}</option>`).join("");$("legacyCategoryFilter").innerHTML='<option value="all">全部分類</option>'+legacyCategories.map(item=>`<option>${item}</option>`).join("");$("budgetCategory").innerHTML=expenseCategories.map(item=>`<option>${item}</option>`).join("");$("transactionMonth").value=now.toLocaleDateString("en-CA").slice(0,7);state.route=location.hash.slice(1)||"home";if(!["home","transactions","savings","settings"].includes(state.route))state.route="home";$("privacyButton").textContent=state.private?"◌":"◉";setRoute(state.route);render();if(ledgerStorageCorrupt||legacyStorageCorrupt)notify("偵測到本機資料損壞，原始內容已另存救援副本",true);retryPendingSync();if("serviceWorker" in navigator)navigator.serviceWorker.register("service-worker.js").catch(error=>console.warn("離線服務註冊失敗",error))}
